#include <generator>
#include <string>
#include <utility>

std::generator<int> naturals(int from)
{
    for (int n{ from };; ++n)
    {
        co_yield n;
    }
}

std::generator<int> primes()
{
    for (int n : naturals(2))
    {
        bool prime{ true };
        for (int d{ 2 }; d * d <= n; ++d)
        {
            if (n % d == 0)
            {
                prime = false;
                break;
            }
        }
        if (prime)
        {
            co_yield n;
        }
    }
}

std::generator<std::string> words(std::string text)
{
    std::string current{};
    for (char c : text)
    {
        if (c == ' ')
        {
            if (!current.empty())
            {
                co_yield std::exchange(current, {});
            }
        }
        else
        {
            current += c;
        }
    }
    if (!current.empty())
    {
        co_yield current;
    }
}

